            neg = -1;
        }
        for (let i = 0; i < s.length; i++) {
            if (s[i] !== '-') {
                sum += parseInt(s[i], 10);
                if (i === 0) {
                    sum *= neg;
                }
            }
        }
        return sum;
    };

    return nums.sort((a, b) => digitsSum(a) - digitsSum(b));
}

