        for (int idx2 = 0; idx2 < numbers.size(); idx2++) {
            if (idx != idx2) {
                float elem = numbers.get(idx);
                float elem2 = numbers.get(idx2);
                float newDistance = Math.abs(elem - elem2);

                if (newDistance < distance) {
