private static long digitsSum(Long n) {
    long sum = 0;
    long neg = 1;
    String s = n.toString();
    if (s.charAt(0) == '-') {
        neg = -1;
        s = s.substring(1);
    }
    for (int i = 0; i < s.length(); i++) {
        int digit = Character.getNumericValue(s.charAt(i));
        if (i == 0) {
            sum += digit * neg;
        } else {
            sum += digit;
        }
    }
    return sum;
}

