func is_nested(string: String) -> Bool {
    var openingBracketIndex: [Int] = []
    var closingBracketIndex: [Int] = []

    for (index, char) in string.enumerated() {
        if char == "[" {
            openingBracketIndex.append(index)
        } else {
            closingBracketIndex.append(index)
        }
    }

    closingBracketIndex.reverse()
    var cnt = 0
    var i = 0
    let l = closingBracketIndex.count

    for idx in openingBracketIndex {
        if i < l && idx < closingBracketIndex[i] {
            cnt += 1
            i += 1
        }
    }

    return cnt >= 2
}

