func order_by_points(nums: [Int]) -> [Int] {
    func digitsSum(_ n: Int) -> Int {
        var sum = 0
        let neg = n < 0 ? -1 : 1
        let string = String(abs(n))

        for (index, char) in string.enumerated() {
            if let digit = char.wholeNumberValue {
                sum += index == 0 ? digit * neg : digit
            }
        }

        return sum
    }

    return nums.sorted(by: { digitsSum($0) < digitsSum($1) })
}

