func circular_shift(x: Int, shift: Int) -> String {
    let s = String(x)
    if shift > s.count {
        return String(s.reversed())
    } else {
        let index = s.index(s.endIndex, offsetBy: -shift)
        let suffix = s[index...]
        let prefix = s[s.startIndex..<index]
        return suffix + prefix
    }
}

