func fib4(n: Int) -> Int {
    var results = [0, 0, 2, 0]
    if n < 4 {
        return results[n]
    }
    for _ in 4...n {
        let nextValue = results.reduce(0, +)
        results.append(nextValue)
        results.removeFirst()
    }
    return results.last!
}

