std::tuple<float, float> find_closest_elements(std::vector<float> numbers) {
    std::tuple<float, float> closest_pair;
    std::optional<float> distance;

    for (size_t idx = 0; idx < numbers.size(); ++idx) {
        float elem = numbers[idx];
        for (size_t idx2 = 0; idx2 < numbers.size(); ++idx2) {
            if (idx != idx2) {
                float elem2 = numbers[idx2];
                if (!distance.has_value()) {
                    distance = std::abs(elem - elem2);
                    closest_pair = std::make_tuple(std::min(elem, elem2), std::max(elem, elem2));
                } else {
                    float new_distance = std::abs(elem - elem2);
                    if (new_distance < distance.value()) {
                        distance = new_distance;
                        closest_pair = std::make_tuple(std::min(elem, elem2), std::max(elem, elem2));
                    }
                }
            }
        }
    }

    return closest_pair;
}

