function sort_even(l: number[]): number[] {
    const evens = l.filter((_, index) => index % 2 === 0).sort((a, b) => a - b);
    const odds = l.filter((_, index) => index % 2 !== 0);
    const ans: number[] = [];

    for (let i = 0; i < evens.length && i < odds.length; i++) {
        ans.push(evens[i]);
        ans.push(odds[i]);
