function find_closest_elements(numbers: number[]): [number, number] {
    let closestPair: [number, number] | null = null;
    let distance: number | null = null;

    for (let idx = 0; idx < numbers.length; idx++) {
        const elem = numbers[idx];
        for (let idx2 = 0; idx2 < numbers.length; idx2++) {
            const elem2 = numbers[idx2];
            if (idx !== idx2) {
                const newDistance = Math.abs(elem - elem2);
                if (distance === null || newDistance < distance) {
                    distance = newDistance;
                    closestPair = [Math.min(elem, elem2), Math.max(elem, elem2)];
                }
            }
        }
    }

    if (closestPair === null) {
        throw new Error("No closest pair found");
    }

    return closestPair;
}

