    for (long i = 1; i <= n; i++) {
        if (i % 2 == 1 && isPalindrome(i)) {
            oddPalindromeCount++;
        } else if (i % 2 == 0 && isPalindrome(i)) {
            evenPalindromeCount++;
        }
    }

    return Pair.with(evenPalindromeCount, oddPalindromeCount);
}

