private static long largestPrimeFactorHelper(long n, long factor) {
    if (factor * factor > n) {
        return n;
    }
    if (n % factor == 0 && isPrime(factor)) {
        return Math.max(factor, largestPrimeFactorHelper(n / factor, factor));
    }
    return largestPrimeFactorHelper(n, factor + 1);
}

