    Pair<Float, Float> closestPair = null;
    float distance = Float.MAX_VALUE;

    for (int idx = 0; idx < numbers.size(); idx++) {
        for (int idx2 = 0; idx2 < numbers.size(); idx2++) {
            if (idx != idx2) {
                float newDistance = Math.abs(numbers.get(idx) - numbers.get(idx2));
                if (newDistance < distance) {
                    distance = newDistance;
                    closestPair = Pair.with(Math.min(numbers.get(idx), numbers.get(idx2)), Math.max(numbers.get(idx), numbers.get(idx2)));
                }
            }
        }
    }

    return closestPair;
}

