fn find_closest_elements(numbers: Vec<f64>) -> (f64, f64) {
    let mut closest_pair = (0.0, 0.0);
    let mut min_distance = f64::MAX;

    for (i, &num1) in numbers.iter().enumerate() {
        for (&num2, _) in numbers.iter().enumerate().skip(i + 1) {
            let distance = (num1 - num2).abs();
            if distance < min_distance {
                min_distance = distance;
                closest_pair = if num1 < num2 { (num1, num2) } else { (num2, num1) };
            }
        }
    }

    closest_pair
}

