    let vowels: HashSet<char> = ['a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U'].iter().cloned().collect();

    for i in (1..word.len() - 1).rev() {
        if vowels.contains(&word.chars().nth(i).unwrap()) {
            let prev_char = word.chars().nth(i - 1).unwrap();
            let next_char = word.chars().nth(i + 1).unwrap();

            if !vowels.contains(&prev_char) && !vowels.contains(&next_char) {
                return word.chars().nth(i).unwrap().to_string();
            }
        }
    }

    String::new()
}

