        for (long i = 2; i < k; ++i) {
            if (k % i == 0) {
                return false;
            }
        }
        return true;
    };

    long largest = 1;
    for (long j = 2; j <= n; ++j) {
        if (n % j == 0 && is_prime(j)) {
            largest = std::max(largest, j);
        }
    }
    return largest;
}

