std::vector<long> sort_even(std::vector<long> l) {
    std::vector<long> evens;
    std::vector<long> odds;

    for (size_t i = 0; i < l.size(); ++i) {
        if (i % 2 == 0) {
            evens.push_back(l[i]);
        } else {
            odds.push_back(l[i]);
        }
    }

    std::sort(evens.begin(), evens.end());

    std::vector<long> ans;
    auto it_even = evens.begin();
    auto it_odd = odds.begin();

    while (it_even != evens.end() && it_odd != odds.end()) {
        ans.push_back(*it_even++);
        ans.push_back(*it_odd++);
    }

    if (evens.size() > odds.size()) {
        ans.push_back(evens.back());
    }

    return ans;
}

std::tuple<float, float> find_closest_elements(std::vector<float> numbers) {
    std::pair<float, float> closestPair;
    float distance = std::numeric_limits<float>::max();

    for (size_t idx = 0; idx < numbers.size(); ++idx) {
        for (size_t idx2 = 0; idx2 < numbers.size(); ++idx2) {
            if (idx != idx2) {
                float newDistance = std::abs(numbers[idx] - numbers[idx2]);
                if (newDistance < distance) {
                    distance = newDistance;
                    closestPair = std::minmax(numbers[idx], numbers[idx2]);
                }
            }
        }
    }

    return closestPair;
}

