bool is_nested(std::string string) {
    std::vector<int> openingBracketIndex;
    std::vector<int> closingBracketIndex;

    for (int i = 0; i < string.length(); ++i) {
        if (string[i] == '[') {
            openingBracketIndex.push_back(i);
        } else {
            closingBracketIndex.push_back(i);
        }
    }

    std::reverse(closingBracketIndex.begin(), closingBracketIndex.end());
    int cnt = 0;
    int i = 0;
    int l = closingBracketIndex.size();

    for (int idx : openingBracketIndex) {
        if (i < l && idx < closingBracketIndex[i]) {
            cnt += 1;
            i += 1;
        }
    }

    return cnt >= 2;
}

